CREATE OR REPLACE PROCEDURE sp(para_StuID integer, para_Sex text, para_ResTypeID integer, para_ResTypeDescription text, para_Rating integer) LANGUAGE plpgsql AS
$$
DECLARE
    cur REFCURSOR;
    rec RECORD;
    temp_num INTEGER;
    temp_text TEXT;
    row_count INTEGER;
    flag INTEGER;
BEGIN
    temp_num := 0;
    temp_text := '';
    row_count := 0;
    flag := 0;
    IF para_StuID < 10 THEN
        UPDATE "Student" SET "Sex" = 'INACTIVE' WHERE "StuID" < para_StuID;
        flag := 1;
    ELSIF para_StuID < 25 THEN
        OPEN cur FOR SELECT "ResTypeID", "ResTypeDescription" FROM "Restaurant_Type" WHERE "ResTypeID" > para_ResTypeID AND "ResTypeDescription" LIKE para_ResTypeDescription FOR UPDATE;
        flag := 2;
    ELSIF para_StuID < 40 THEN
        OPEN cur FOR SELECT "Rating" FROM "Restaurant" WHERE "Rating" BETWEEN para_Rating AND para_Rating * 2;
        flag := 3;
    ELSE
        OPEN cur FOR SELECT "StuID", "Sex" FROM "Student" WHERE "StuID" > para_StuID / 2;
        flag := 4;
    END IF;
    IF flag = 2 OR flag = 3 OR flag = 4 THEN
        LOOP
            FETCH cur INTO rec;
            EXIT WHEN NOT FOUND;
            row_count := row_count + 1;
            IF flag = 2 THEN
                IF rec."ResTypeID" < 50 THEN
                    UPDATE "Restaurant_Type" SET "ResTypeDescription" = 'COMPLETED' WHERE CURRENT OF cur;
                ELSE
                    temp_num := temp_num + rec."ResTypeID";
                END IF;
            ELSIF flag = 3 THEN
                IF rec."Rating" > 100 THEN
                    temp_text := 'OVER_LIMIT';
                ELSIF rec."Rating" > 50 THEN
                    temp_text := 'WITHIN_RANGE';
                ELSE
                    temp_text := 'BELOW_MIN';
                END IF;
            ELSIF flag = 4 THEN
                IF rec."StuID" % 2 = 0 THEN
                    temp_num := temp_num + 1;
                END IF;
            END IF;
        END LOOP;
        CLOSE cur;
    END IF;
    IF flag = 1 THEN
        DELETE FROM "Restaurant_Type" WHERE "ResTypeID" < para_ResTypeID;
    ELSIF flag = 2 AND temp_num > 100 THEN
        UPDATE "Restaurant" SET "Rating" = "Rating" - 10 WHERE "Rating" > 200;
    ELSIF flag = 3 AND temp_text = 'OVER_LIMIT' THEN
        DELETE FROM "Restaurant" WHERE "Rating" > 150;
    ELSIF flag = 4 AND temp_num > 5 THEN
        UPDATE "Student" SET "Sex" = 'PROCESSED' WHERE "StuID" < para_StuID;
    ELSE
        UPDATE "Restaurant_Type" SET "ResTypeDescription" = 'DEFAULT' WHERE "ResTypeID" IS NULL;
    END IF;
END;
$$;

